const ask = $('Called as a tool').first().json;
const res = $input.first().json;
if (res.errors?.length) throw new Error(`Linear refused the lookup: ${res.errors[0].message}`);
const title = String(ask.title ?? '').trim();
if (!title) throw new Error('title is required');
const team = res.data?.teams?.nodes?.[0];
if (!team) throw new Error(`no Linear team with key ${String(ask.team ?? '').trim().toUpperCase() || '(none given)'}`);
const want = String(ask.label ?? '').trim();
// A workspace label, or one of this team's; another team's label cannot go on this team's issue.
const label = want ? (res.data?.issueLabels?.nodes ?? []).find((l) => !l.team || l.team.id === team.id) : undefined;
return [{ json: { teamId: team.id, teamKey: team.key, title, description: String(ask.description ?? ''), labelName: want, labelId: label?.id ?? null, needLabel: Boolean(want && !label) } }];

const p = $('Pick the team and label').first().json;
const res = $input.first().json;
if (res.errors?.length) throw new Error(`Linear refused the label: ${res.errors[0].message}`);
const labelId = p.labelId ?? res.data?.issueLabelCreate?.issueLabel?.id ?? null;
if (p.needLabel && !labelId) throw new Error(`the label ${p.labelName} could not be created`);
const input = { teamId: p.teamId, title: p.title, description: p.description, ...(labelId ? { labelIds: [labelId] } : {}) };
return [{ json: { body: { query: 'mutation($input: IssueCreateInput!) { issueCreate(input: $input) { success issue { identifier title url } } }', variables: { input } } } }];

const res = $input.first().json;
const made = res.data?.issueCreate;
if (res.errors?.length || !made?.success) throw new Error(`Linear did not create the issue: ${res.errors?.[0]?.message ?? 'no success flag'}`);
return [{ json: { identifier: made.issue.identifier, title: made.issue.title, url: made.issue.url } }];
